import json
import re

def extract_info_from_email(email_content):
    pattern = r"Error Code: (.+)\.\s+(.+)@(.+)\.com\s+\((.+)\)"
    match = re.search(pattern, email_content)
    if match:
        error_message = match.group(1)
        contact_details = {
            "email": match.group(2),
            "phone": match.group(4)
        }
        return json.dumps({"error_message": error_message, "contact_details": contact_details})
    else:
        return json.dumps({"error": "Invalid email format"})

