import email
import json

def extract_refund_info(email_content):
    try:
        email_message = email.message_from_string(email_content)
        sender = email_message['From']
        date_of_event = email_message['Date']
        body = email_message.get_payload()
        refund_info = {}
        for line in body.split('\n'):
            if 'refund' in line:
                refund_parts = line.split(':')
                refund_info['type'] = refund_parts[0].strip()
                refund_info['amount_refunded'] = refund_parts[1].strip().replace('$', '')
                break
        refund_info['sender'] = sender
        refund_info['date_of_event'] = date_of_event
        refund_info['method_of_refund'] = 'manual'
        refund_info = {k: v for k, v in refund_info.items() if v}
        return json.dumps(refund_info)
    except Exception as e:
        print(f"Error occurred: {str(e)}")
        return None

