def parse_text_to_json(text):
    import json
    data = {}
    claim = {}
    claim["Name"] = ""
    claim["Email"] = ""
    claim["Type of Claim"] = ""
    claim["Date of Incident"] = ""
    claim["Time of Incident"] = ""
    claim["Location of Incident"] = ""
    claim["Description of Incident"] = ""
    documentation = []

    lines = text.split("\n")

    for line in lines:
        if "Claimant Name:" in line:
            claim["Name"] = line.split(":")[1].strip().split()[0]
            claim["Email"] = lines[lines.index(line) + 1].split(":")[1].strip().split()[1]
        elif "Type of Claim:" in line:
            claim["Type of Claim"] = line.split(":")[1].strip()
        elif "Date of Incident:" in line:
            claim["Date of Incident"] = line.split(":")[1].strip()
        elif "Time of Incident:" in line:
            claim["Time of Incident"] = line.split(":")[1].strip()
        elif "Location of Incident:" in line:
            claim["Location of Incident"] = line.split(":")[1].strip()
        elif "Description of Incident:" in line:
            claim["Description of Incident"] = line.split(":")[1].strip()
        elif "Documentation Required:" in line:
            documentation = line.split(":")[1].strip().split(",")

    data["Claimant"] = claim
    data["Documentation Required"] = documentation

    return json.dumps(data)

