function extract_claim_info(text) {
  const claim_info = JSON.parse('{"claimant":{},"type":"", "date_of_incident":"", "time_of_incident":"", "location":{}, "description":""}');
  const regex = /Claimant Name: (.+)\nType of Claim: (.+)\nDate: (.+)\nTime: (.+)\nLocation: (.+)\nDescription: (.+)/g;
  const match = regex.exec(text);

  if (match) {
    claim_info.claimant.name = match[1];
    claim_info.type = match[2];
    claim_info.date_of_incident = match[3];
    claim_info.time_of_incident = match[4];
    claim_info.location.street = match[5].match(/Intersection of (.+) and (.+)/)[1];
    claim_info.description = match[6];
    return JSON.stringify(claim_info);
  } else {
    throw new Error("Invalid text format. Please provide a text in the following format: Claimant Name: [Name] Type of Claim: [Type] Date: [Date] Time: [Time] Location: [Location] Description: [Description]");
  }
}

