def extract_info(email):
    pattern = r"Error Code: (.+)\n(.+)Contact Details:\s+(.+)Email:\s+(.+)\nPhone:\s+(.+)"
    match = re.search(pattern, email)
    if match:
        error_message = match.group(1)
        contact_details = {"email": match.group(4), "phone": match.group(5)}
        return json.dumps({"error_message": error_message, "contact_details": contact_details})
    else:
        return json.dumps({"error": "Invalid email format"})

