// Create a JSON object from an email
function createJsonObjectFromEmail(emailText) {
  // Parse the email text to extract the required data
  const emailData = emailText.match(/From: (.*)\r\nSubject: (.*)\r\nAccount Number: (.*)\r\nOrder Number: (.*)/g)[0].slice(1).map(str => str.trim().split(': ')[1]);

  // Validate the input data
  if (!emailData || emailData.length !== 4) {
    throw new Error("Invalid email format.");
  }

  // Generate the JSON object
  const jsonObject = {
    sender: emailData[0],
    subject: emailData[1],
    account_number: emailData[2],
    order_number: emailData[3]
  };

  return jsonObject;
}

