function extract_email_fields(email_content) {
  const regex = /Subject: (.*)\nSender: (.*)\nDate: (.*)\nReason_for_Request: (.*)\nAccount_Number: (.*)/g;
  const match = regex.exec(email_content);

  if (!match) {
    throw new Error("Invalid email content.");
  }

  const fields = {
    Subject: match[1],
    Sender: match[2],
    Date: match[3],
    Reason_for_Request: match[4],
    Account_Number: match[5]
  };

  const date_regex = /(\d{1,2})(\/|-)(0?[1-9]|1[0-2])(\/|-)([12]\d{3})/g;
  const date_match = date_regex.exec(fields.Date);

  if (!date_match) {
    throw new Error("Invalid date format.");
  }

  fields.Date = new Date(date_match[0]);

  return fields;
}

